-- an IN list of 1000 ids through the access method: the point directory looks each key up (up to 64 keys it did; a longer list was answered by the units)
-- label: `SELECT id, amount, title WHERE id IN (<1000 ids>)`, no btree on `id`, `point_tid_columns = 'id'`
-- ordered: yes
-- set: sift.enable_col_scan = on
--@ setup
